import { Component, OnInit, Inject, ChangeDetectionStrategy } from '@angular/core';
import { MatCheckboxChange } from '@angular/material/checkbox';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';

@Component({
    selector: 'app-alert-dialog',
    templateUrl: './alert-dialog.component.html',
    styleUrls: ['./alert-dialog.component.scss'],
    changeDetection: ChangeDetectionStrategy.Eager,
    standalone: false,
})
export class AlertDialogComponent implements OnInit {
    public title: string;
    public message: string;
    public dontshow: string;
    public subkey: string;
    dontshowanymore: boolean;

    constructor(
        @Inject(MAT_DIALOG_DATA)
        private data: {
            Message: string;
            Title: string;
            DontShow: string;
            SubKey: string;
        },
        private mdDialogRef: MatDialogRef<AlertDialogComponent>,
    ) {
        this.title = '';
        this.message = '';
        this.dontshow = '';
        this.subkey = '';
        this.dontshowanymore = false;
    }

    ngOnInit() {
        this.title = this.data.Title;
        this.message = this.data.Message;
        this.dontshow = this.data.DontShow;
        this.subkey = this.data.SubKey;
    }

    showOptions(event: Event): void {
        if (this.dontshowanymore)
            // document.cookie =
            localStorage.setItem('DONTSHOWUPDATEWARN', this.message);
        else localStorage.removeItem('DONTSHOWUPDATEWARN');
    }
    public closeDialog() {
        this.mdDialogRef.close();
    }
}
